// job-plan.js — deterministic dependency planning over a job graph.
//
// Exports planJobs(spec) (synchronous, pure, read-only over its input) and,
// when executed directly, a small CLI:
//
//   node job-plan.js SPECFILE
//
// which reads a UTF-8 JSON spec and prints the plan as JSON plus a newline.

import { readFileSync, realpathSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

// Code-unit string order: exactly the JavaScript `<` / `>` ordering for
// strings (UTF-16 code units, no locale collation).
function cmpStrings(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

// Binary min-heap of ids ordered with cmpStrings.
class IdMinHeap {
  constructor() {
    this.items = [];
  }

  get size() {
    return this.items.length;
  }

  push(id) {
    const items = this.items;
    items.push(id);
    let i = items.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (cmpStrings(items[parent], items[i]) <= 0) break;
      [items[parent], items[i]] = [items[i], items[parent]];
      i = parent;
    }
  }

  pop() {
    const items = this.items;
    const top = items[0];
    const last = items.pop();
    if (items.length > 0) {
      items[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < items.length && cmpStrings(items[left], items[smallest]) < 0) {
          smallest = left;
        }
        if (right < items.length && cmpStrings(items[right], items[smallest]) < 0) {
          smallest = right;
        }
        if (smallest === i) break;
        [items[smallest], items[i]] = [items[i], items[smallest]];
        i = smallest;
      }
    }
    return top;
  }
}

export function planJobs(spec) {
  if (!Array.isArray(spec)) {
    throw new Error('spec must be an array of job objects');
  }

  // Validate every job and register it. A Map keeps ids such as
  // "__proto__" or "constructor" as ordinary keys. Unknown fields are
  // ignored and the input is never mutated.
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job)) {
      throw new Error('every entry of spec must be a job object');
    }
    const { id, deps, state } = job;
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('every job needs an "id" that is a nonempty string');
    }
    if (jobs.has(id)) {
      throw new Error(`duplicate job id ${JSON.stringify(id)}`);
    }
    if (!Array.isArray(deps)) {
      throw new Error(`job ${JSON.stringify(id)} needs a "deps" array`);
    }
    const seen = new Set();
    for (const dep of deps) {
      if (typeof dep !== 'string' || dep.length === 0) {
        throw new Error(`job ${JSON.stringify(id)} has a dependency that is not a nonempty string`);
      }
      if (seen.has(dep)) {
        throw new Error(`job ${JSON.stringify(id)} lists dependency ${JSON.stringify(dep)} more than once`);
      }
      seen.add(dep);
    }
    if (state !== 'pending' && state !== 'succeeded' && state !== 'failed') {
      throw new Error(`job ${JSON.stringify(id)} has an invalid state; expected pending, succeeded, or failed`);
    }
    jobs.set(id, { id, deps, state });
  }

  // Every referenced dependency must exist.
  for (const { id, deps } of jobs.values()) {
    for (const dep of deps) {
      if (!jobs.has(dep)) {
        throw new Error(`job ${JSON.stringify(id)} depends on unknown id ${JSON.stringify(dep)}`);
      }
    }
  }

  // Kahn's algorithm over the ENTIRE graph (all states), always removing
  // the code-unit-smallest currently zero-indegree id and updating its
  // children before choosing again. Any id left unprocessed is part of, or
  // downstream of, a directed cycle (a self-dependency included).
  const dependents = new Map(); // id -> jobs that list it as a dependency
  const indegree = new Map();   // id -> number of not-yet-removed dependencies
  for (const { id, deps } of jobs.values()) {
    indegree.set(id, deps.length);
    for (const dep of deps) {
      const list = dependents.get(dep);
      if (list === undefined) dependents.set(dep, [id]);
      else list.push(id);
    }
  }
  const frontier = new IdMinHeap();
  for (const [id, count] of indegree) {
    if (count === 0) frontier.push(id);
  }
  const topo = [];
  while (frontier.size > 0) {
    const id = frontier.pop();
    topo.push(id);
    for (const child of dependents.get(id) ?? []) {
      const count = indegree.get(child) - 1;
      indegree.set(child, count);
      if (count === 0) frontier.push(child);
    }
  }
  if (topo.length !== jobs.size) {
    throw new Error('dependency graph contains a cycle');
  }

  // For every id: the set of failed jobs reachable along dependency paths.
  // Intermediate states never erase ancestry. Topological order guarantees
  // each dependency's set is already computed.
  const failedAncestors = new Map();
  for (const id of topo) {
    const set = new Set();
    for (const dep of jobs.get(id).deps) {
      const inherited = failedAncestors.get(dep);
      if (inherited !== undefined) {
        for (const failed of inherited) set.add(failed);
      }
      if (jobs.get(dep).state === 'failed') set.add(dep);
    }
    failedAncestors.set(id, set);
  }

  const order = [];
  const ready = [];
  const blocked = [];
  for (const id of topo) {
    const { state, deps } = jobs.get(id);
    if (state !== 'pending') continue; // failed/succeeded never appear below
    const causes = failedAncestors.get(id);
    if (causes.size > 0) {
      blocked.push({ id, causes: [...causes].sort() });
      continue;
    }
    order.push(id); // full order filtered to unblocked pending jobs
    let allSucceeded = true;
    for (const dep of deps) {
      if (jobs.get(dep).state !== 'succeeded') {
        allSucceeded = false;
        break;
      }
    }
    if (allSucceeded) ready.push(id);
  }
  ready.sort();
  blocked.sort((a, b) => cmpStrings(a.id, b.id));
  return { order, ready, blocked };
}

function cliFail(message) {
  process.stderr.write(`${message}\n`);
  process.exitCode = 2;
}

function runCli(args) {
  if (args.length !== 1) {
    cliFail('usage: node job-plan.js SPECFILE');
    return;
  }
  const [file] = args;
  let raw;
  try {
    raw = readFileSync(file, 'utf8');
  } catch (err) {
    cliFail(`cannot read ${file}: ${err.message}`);
    return;
  }
  let spec;
  try {
    spec = JSON.parse(raw.replace(/^\uFEFF/, ''));
  } catch (err) {
    cliFail(`invalid JSON in ${file}: ${err.message}`);
    return;
  }
  let plan;
  try {
    plan = planJobs(spec);
  } catch (err) {
    cliFail(`invalid job spec: ${err.message}`);
    return;
  }
  process.stdout.write(`${JSON.stringify(plan)}\n`);
}

const isDirectRun = (() => {
  const entry = process.argv[1];
  if (typeof entry !== 'string' || entry.length === 0) return false;
  try {
    return realpathSync(entry) === realpathSync(pathToFileURL(import.meta.url));
  } catch {
    return false;
  }
})();

if (isDirectRun) {
  runCli(process.argv.slice(2));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('kahn picks the smallest newly freed id each time, not waves or input order', () => {
  // indegrees: c:0, z:0, a:1, m:1, b:2, y:1
  const spec = [job('c'), job('a', ['c']), job('m', ['c']), job('b', ['a', 'm']), job('z'), job('y', ['z'])];
  assert.deepEqual(planJobs(spec), {
    order: ['c', 'a', 'm', 'b', 'z', 'y'],
    ready: ['c', 'z'],
    blocked: [],
  });
});

test('order comes from the full graph, not the induced pending-only graph', () => {
  // full frontier starts at {q, s}: "q" < "s", so q is removed first even
  // though it is unrelated to the pending chain p -> s.
  const spec = [job('s', [], 'succeeded'), job('p', ['s']), job('q')];
  assert.deepEqual(planJobs(spec), { order: ['q', 'p'], ready: ['p', 'q'], blocked: [] });
});

test('a pending direct dependency prevents readiness; no deps means ready', () => {
  assert.deepEqual(planJobs([job('a'), job('b', ['a'])]), {
    order: ['a', 'b'],
    ready: ['a'],
    blocked: [],
  });
});

test('readiness needs every direct dependency succeeded (snapshot of input states)', () => {
  assert.deepEqual(planJobs([job('a', [], 'succeeded'), job('b', [], 'succeeded'), job('c', ['a', 'b'])]), {
    order: ['c'],
    ready: ['c'],
    blocked: [],
  });
});

test('transitive failure through a succeeded middle job still blocks', () => {
  const spec = [job('f', [], 'failed'), job('s', ['f'], 'succeeded'), job('p', ['s'])];
  assert.deepEqual(planJobs(spec), {
    order: [],
    ready: [],
    blocked: [{ id: 'p', causes: ['f'] }],
  });
});

test('causes are unique, complete across paths, and code-unit sorted', () => {
  const spec = [
    job('bf', [], 'failed'),
    job('af', [], 'failed'),
    job('g', ['af']),
    job('h', ['bf', 'af']),
    job('i', ['h', 'g'], 'succeeded'),
    job('top', ['i', 'af']),
  ];
  assert.deepEqual(planJobs(spec), {
    order: [],
    ready: [],
    blocked: [{ id: 'top', causes: ['af', 'bf'] }],
  });
});

test('blocked entries are sorted by id; multiple failed direct deps all listed', () => {
  const spec = [
    job('f2', [], 'failed'),
    job('z', ['f2']),
    job('a', ['f2', 'f1']),
    job('f1', [], 'failed'),
    job('m', ['f1']),
  ];
  assert.deepEqual(planJobs(spec), {
    order: [],
    ready: [],
    blocked: [
      { id: 'a', causes: ['f1', 'f2'] },
      { id: 'm', causes: ['f1'] },
      { id: 'z', causes: ['f2'] },
    ],
  });
});

test('result is independent of input order', () => {
  const base = [job('z'), job('b'), job('a', ['b']), job('w', ['a'])];
  assert.deepEqual(planJobs(base), planJobs([...base].reverse()));
  assert.deepEqual(planJobs(base), { order: ['b', 'a', 'w', 'z'], ready: ['b', 'z'], blocked: [] });
});

test('ids with whitespace and unicode are exact and code-unit ordered', () => {
  const spec = [job('b'), job(' b'), job('\u00e9'), job('z')];
  // code units: ' ' (0x20) < 'b' (0x62) < 'z' (0x7A) < '\u00e9' (0xE9)
  assert.deepEqual(planJobs(spec), {
    order: [' b', 'b', 'z', '\u00e9'],
    ready: [' b', 'b', 'z', '\u00e9'],
    blocked: [],
  });
});

test('__proto__ and constructor are ordinary ids (keys and dependencies)', () => {
  const spec = [
    { id: '__proto__', deps: [], state: 'pending' },
    { id: 'constructor', deps: ['__proto__'], state: 'pending' },
    { id: 'hasOwnProperty', deps: ['constructor', '__proto__'], state: 'failed' },
  ];
  assert.deepEqual(planJobs(spec), {
    order: ['__proto__', 'constructor'],
    ready: ['__proto__'],
    blocked: [],
  });
  assert.deepEqual(
    planJobs([
      { id: 'x', deps: ['__proto__', 'constructor'], state: 'pending' },
      { id: '__proto__', deps: [], state: 'succeeded' },
      { id: 'constructor', deps: [], state: 'succeeded' },
    ]),
    { order: ['x'], ready: ['x'], blocked: [] },
  );
  assert.throws(() => planJobs([{ id: '__proto__', deps: [], state: 'pending' }, { id: '__proto__', deps: [], state: 'failed' }]));
});

test('cycles anywhere in the graph throw, including self-deps and completed jobs', () => {
  assert.throws(() => planJobs([job('a', ['b']), job('b', ['a'])]), Error);
  assert.throws(() => planJobs([job('a', ['a'])]), Error);
  assert.throws(() => planJobs([job('a', ['b'], 'succeeded'), job('b', ['a'], 'failed')]), Error);
  assert.throws(() => planJobs([job('a', ['b']), job('b', ['c']), job('c', ['a']), job('d', [], 'failed')]), Error);
  assert.throws(() => planJobs([job('a', ['b']), job('b', ['a'], 'succeeded'), job('c', [], 'succeeded')]), Error);
});

test('duplicate ids, unknown references, and duplicate dependencies throw', () => {
  assert.throws(() => planJobs([job('a'), job('a')]), Error);
  assert.throws(() => planJobs([job('a'), job('a', [], 'failed')]), Error);
  assert.throws(() => planJobs([job('a', ['absent'])]), Error);
  assert.throws(() => planJobs([job('a', ['a', 'a'])]), Error);
  assert.throws(() => planJobs([job('a', ['b', 'b']), job('b')]), Error);
});

test('malformed required fields throw (no coercion)', () => {
  const badSpecs = [
    null, 42, 'x', {}, () => {},
    [null], [42], ['x'], [[]], [true],
    [{ id: 'a', deps: [] }], // missing state
    [{ deps: [], state: 'pending' }], // missing id
    [{ id: 'a', state: 'pending' }], // missing deps
    [job('a', null)],
    [job('a', 'a')],
    [job('a', [1])],
    [job('a', [''])],
    [job('a', [null])],
    [job('a', ['a', 1])],
    [job('a', [], 'done')],
    [job('a', [], 'Pending')],
    [job('a', [], ' ')],
    [job('a', [], 1)],
    [job('a', [], null)],
    [job('', [])],
    [job(1, [])],
    [job(null, [])],
  ];
  for (const bad of badSpecs) {
    assert.throws(() => planJobs(bad), Error, `expected throw for ${JSON.stringify(bad) ?? String(bad)}`);
  }
});

test('unknown fields are ignored and the input is not mutated', () => {
  const spec = [
    { id: 'b', deps: ['a'], state: 'pending', name: 'build', priority: 5, meta: { deep: [1, 2] } },
    { id: 'a', deps: [], state: 'pending', note: '' },
  ];
  const snapshot = structuredClone(spec);
  const result = planJobs(spec);
  assert.deepEqual(spec, snapshot);
  assert.deepEqual(result, { order: ['a', 'b'], ready: ['a'], blocked: [] });
});

test('failed and succeeded jobs never appear in order or blocked', () => {
  const spec = [
    job('ok', [], 'succeeded'),
    job('bad', [], 'failed'),
    job('mid', ['bad']),
    job('fine', ['ok']),
    job('also', ['bad'], 'succeeded'),
  ];
  assert.deepEqual(planJobs(spec), {
    order: ['fine'],
    ready: ['fine'],
    blocked: [{ id: 'mid', causes: ['bad'] }],
  });
});

test('importing the module exposes planJobs and nothing is executed', async () => {
  const mod = await import('../job-plan.js');
  assert.equal(typeof mod.planJobs, 'function');
});

// --- CLI ---

const cliPath = fileURLToPath(new URL('../job-plan.js', import.meta.url));

function runCli(args) {
  return spawnSync(process.execPath, [cliPath, ...args], { encoding: 'utf8' });
}

test('cli prints only the plan json plus newline and exits 0', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  try {
    const file = join(dir, 'spec.json');
    writeFileSync(file, JSON.stringify([job('b', ['a']), job('a'), job('f', [], 'failed')]));
    const res = runCli([file]);
    assert.equal(res.status, 0);
    assert.equal(res.stderr, '');
    assert.equal(res.stdout, `${JSON.stringify({ order: ['a', 'b'], ready: ['a'], blocked: [] })}\n`);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('cli errors exit 2 with nonempty stderr and no stdout', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  try {
    const good = join(dir, 'good.json');
    writeFileSync(good, JSON.stringify([job('a')]));
    const badJson = join(dir, 'bad.json');
    writeFileSync(badJson, '{not json');
    const badGraph = join(dir, 'cycle.json');
    writeFileSync(badGraph, JSON.stringify([job('a', ['b']), job('b', ['a'])]));
    const notArray = join(dir, 'notarray.json');
    writeFileSync(notArray, '{"id":"a","deps":[],"state":"pending"}');
    const cases = [
      [], // no args
      [good, good], // too many args
      [join(dir, 'missing.json')], // unreadable input
      [dir], // directory is not a file
      [badJson], // invalid JSON
      [badGraph], // invalid graph (cycle)
      [notArray], // invalid spec shape
    ];
    for (const args of cases) {
      const res = runCli(args);
      assert.equal(res.status, 2, `expected exit 2 for ${JSON.stringify(args)}`);
      assert.equal(res.stdout, '');
      assert.ok(res.stderr.length > 0, `expected nonempty stderr for ${JSON.stringify(args)}`);
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

