cd /workspace && od -c /tmp/out.txt | tail -3 && cat > /tmp/prop.mjs <<'EOF'
import { planJobs } from '/workspace/job-plan.js';

// Independent reference: brute-force per-job DFS + array-scan topological sort.
function reference(spec) {
  const jobs = new Map(spec.map(j => [j.id, j]));
  // topological order: repeatedly scan for the smallest lex zero-indegree id
  const indeg = new Map([...jobs.keys()].map(id => [id, jobs.get(id).deps.length]));
  const topo = [];
  while (topo.length < jobs.size) {
    let pick = null;
    for (const id of jobs.keys()) {
      if (indeg.get(id) === 0 && (pick === null || id < pick)) pick = id;
    }
    if (pick === null) throw new Error('cycle');
    topo.push(pick);
    indeg.set(pick, -1);
    for (const [id, j] of jobs) {
      if (j.deps.includes(pick) && indeg.get(id) > 0) indeg.set(id, indeg.get(id) - 1);
    }
  }
  // failed ancestors by DFS with memo over the whole graph
  const memo = new Map();
  function ancestors(id, visiting) {
    if (memo.has(id)) return memo.get(id);
    if (visiting.has(id)) throw new Error('cycle');
    visiting.add(id);
    const set = new Set();
    for (const dep of jobs.get(id).deps) {
      for (const f of ancestors(dep, visiting)) set.add(f);
      if (jobs.get(dep).state === 'failed') set.add(dep);
    }
    visiting.delete(id);
    memo.set(id, set);
    return set;
  }
  for (const id of topo) ancestors(id, new Set());
  const order = [], ready = [], blocked = [];
  for (const id of topo) {
    const j = jobs.get(id);
    if (j.state !== 'pending') continue;
    const fails = ancestors(id, new Set());
    if (fails.size > 0) blocked.push({ id, causes: [...fails].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)) });
    else {
      order.push(id);
      if (j.deps.every(d => jobs.get(d).state === 'succeeded')) ready.push(id);
    }
  }
  ready.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  blocked.sort((x, y) => (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
  return { order, ready, blocked };
}

function rnd(n) { return Math.floor(Math.random() * n); }
function randId(i, alphabet) {
  // mix plain ascii, whitespace, and unicode to stress code-unit ordering
  const chars = alphabet[rnd(alphabet.length)];
  return `${chars}${i.toString(16)}`;
}

const alphabets = [
  ['a','b','c','d','e'],
  ['a','B','z','_','0',' ','\t'],
  ['\u00e9','\u4e2d','\ud83d\u0000','a','z','\u0001','\uffff'],
];

for (let iter = 0; iter < 3000; iter++) {
  const n = 1 + rnd(14);
  const alphabet = alphabets[rnd(alphabets.length)];
  const ids = [];
  const used = new Set();
  for (let i = 0; i < n; i++) {
    let id;
    do { id = randId(i, alphabet); } while (used.has(id));
    used.add(id);
    ids.push(id);
  }
  const spec = ids.map((id, i) => {
    // only deps on earlier ids => guaranteed DAG
    const deps = [];
    for (let j = 0; j < i; j++) if (Math.random() < 0.3) deps.push(ids[j]);
    const r = Math.random();
    const state = r < 0.55 ? 'pending' : r < 0.8 ? 'succeeded' : 'failed';
    return { id, deps, state, extra: { x: 1 } };
  });
  const a = planJobs(spec);
  const b = reference(spec);
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    console.error('MISMATCH at iter', iter);
    console.error(JSON.stringify(spec, null, 1));
    console.error('actual  :', JSON.stringify(a));
    console.error('expected:', JSON.stringify(b));
    process.exit(1);
  }
}
console.log('property check OK: 3000 random DAGs match reference');

// determinism under input permutation on one fixed tricky graph
const spec = [
  { id: 'z', deps: [], state: 'pending' },
  { id: ' b', deps: [], state: 'pending' },
  { id: 'a', deps: [' b'], state: 'pending' },
  { id: 'b', deps: [], state: 'succeeded' },
  { id: 'y', deps: ['a'], state: 'failed' },
];
const base = planJobs(spec);
for (let k = 0; k < 200; k++) {
  const perm = [...spec].sort(() => Math.random() - 0.5);
  if (JSON.stringify(planJobs(perm)) !== JSON.stringify(base)) {
    console.error('input-order sensitivity detected'); process.exit(1);
  }
}
console.log('input-order determinism OK');
